import json,re
from osgr import gr
arts=json.load(open('arts.json')); wl=json.load(open('wl.json'))
WP="Wikipedia"
def A(t):
    v=arts[t]; return v['url'],v['lat'],v['lon']
def W(i):
    w=wl[i]
    if w['lat'] is None:
        m=re.search(r'(5\d\.\d+); (-\d\.\d+)',w['details']); return w['page'],float(m[1]),float(m[2])
    return w['page'],w['lat'],w['lon']
CF="https://coflein.gov.uk/en/site/"
R=[]
def a(name,cat,ref,desc,source=WP,coords=None,url=None):
    if isinstance(ref,int): u,la,lo=W(ref)
    elif ref.startswith('GR:'): u=url; la,lo=gr(ref[3:])
    else: u,la,lo=A(ref)
    if url: u=url
    if coords: la,lo=coords
    R.append(dict(name=name,cat=cat,lat=round(la,5),lon=round(lo,5),desc=desc,source=source,url=u))
